from fastapi.openapi.docs import get_swagger_ui_html
from fastapi.responses import HTMLResponse

def test_swagger_ui_escaping():
    # Test swagger_ui_parameters escaping
    params = {"test_key<": "test_value>"}
    html = get_swagger_ui_html(openapi_url="/openapi.json", title="Test", swagger_ui_parameters=params).body.decode("utf-8")
    assert "\\u003c" in html
    assert "\\u003e" in html
    assert "<script>" not in html # Should not be present if we use a script tag in value

    # Test init_oauth escaping
    init_oauth = {"client_id": "<script>alert(1)</script>"}
    html = get_swagger_ui_html(openapi_url="/openapi.json", title="Test", init_oauth=init_oauth).body.decode("utf-8")
    assert "\\u003c" in html
    assert "\\u003e" in html
    assert "<script>" not in html

if __name__ == "__main__":
    try:
        test_swagger_ui_escaping()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

from fastapi.openapi.docs import get_swagger_ui_html

def test_swagger_ui_escaping():
    # Test swagger_ui_parameters escaping
    params = {"test_key<": "test_value>"}
    html = get_swagger_ui_html(openapi_url="/openapi.json", title="Test", swagger_ui_parameters=params).body.decode("utf-8")
    # The key "test_key<" should be dumped as "test_key\u003c"
    assert '"test_key\\u003c"' in html
    # The value "test_value>" should be dumped as "test_value\u003e"
    assert '"test_value\\u003e"' in html

    # Test init_oauth escaping
    init_oauth = {"client_id": "<script>alert(1)</script>"}
    html = get_swagger_ui_html(openapi_url="/openapi.json", title="Test", init_oauth=init_oauth).body.decode("utf-8")
    assert '"client_id": "\\u003cscript\\u003ealert(1)\\u003c/script\\u003e"' in html

if __name__ == "__main__":
    try:
        test_swagger_ui_escaping()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

